        assertNon200Throws(400);
    }

    @IsTest
    static void status404ThrowsExceptionWithStatusCode() {
        assertNon200Throws(404);
    }

    @IsTest
    static void status500ThrowsExceptionWithStatusCode() {
        assertNon200Throws(500);
    }

    @IsTest
    static void verifiedResponseLeavesAccountUntouched() {
        Account acct = buildAccount();
        Test.setMock(HttpCalloutMock.class, new ContractMock(200,
