@IsTest
private class RenewalServiceTest {

    // =================================================================================================
    // Pure unit tests for RenewalService.createRenewals: no DML, no SOQL.
    //
    // The selector and the unit of work are mocked with fflib_ApexMocks and injected through the
    // Application factory setMock methods. The records the service creates never receive ids
    // (registerNew is mocked, so registerNew never assigns an id), therefore the expected records
    // are rebuilt here exactly as the service contract specifies and compared against the actual
    // arguments passed to the mocked unit of work.
    //
    // Note: only core fflib_ApexMocks APIs are used (mock, startStubbing, when/thenReturn,
    // verify, times) together with concrete expected arguments, so no matcher classes are required.
    // =================================================================================================

    private static fflib_ISObjectUnitOfWork mockUnitOfWork(fflib_ApexMocks mocks) {
        fflib_ISObjectUnitOfWork mockUow = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);
        Application.UnitOfWork.setMock(mockUow);
        return mockUow;
    }

    private static IOpportunitiesSelector mockSelector(fflib_ApexMocks mocks) {
        IOpportunitiesSelector mockSelector = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        Application.Selector.setMock(mockSelector);
        return mockSelector;
    }

    private static void stubSelectById(
        fflib_ApexMocks mocks,
        IOpportunitiesSelector mockSelector,
        Set<Id> opportunityIds,
        List<Opportunity> result
    ) {
        mocks.startStubbing();
        mocks.when(mockSelector.selectById(opportunityIds)).thenReturn(result);
        mocks.stopStubbing();
    }

    private static Opportunity makeOpportunity(
        String name,
        Id accountId,
        Id ownerId,
        String stageName,
        Date closeDate,
        Decimal amount
    ) {
        Opportunity opp = new Opportunity(
            Name = name,
            AccountId = accountId,
            OwnerId = ownerId,
            StageName = stageName,
            CloseDate = closeDate,
            Amount = amount
        );
        opp.Id = fflib_IDGenerator.generate(Opportunity.SObjectType);
        return opp;
    }

    // Rebuilds the renewal exactly as the contract requires (same fields, same explicit-null
    // handling), so it can be compared against the record actually passed to registerNew.
    private static Opportunity expectedRenewalFor(Opportunity original) {
        return new Opportunity(
            Name = original.Name + ' - Renewal',
            AccountId = original.AccountId,
            StageName = 'Prospecting',
            CloseDate = original.CloseDate.addYears(1),
            Amount = original.Amount == null ? null : (original.Amount * RenewalService.UPLIFT).setScale(2)
        );
    }

    // Rebuilds the expected reminder Task. WhatId is intentionally not populated on the record
    // itself: the relation to the new renewal is expressed by the registerNew(task, Task.WhatId,
    // renewal) arguments, which are verified below.
    private static Task expectedReminderFor(Opportunity original, Opportunity renewal) {
        return new Task(
            Subject = 'Prepare renewal for ' + original.Name,
            OwnerId = original.OwnerId,
            ActivityDate = renewal.CloseDate.addDays(-60)
        );
    }

    @IsTest
    static void renewsEveryClosedWonOpportunityAndRegistersReminderAgainstTheNewRenewal() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector mockSelector = mockSelector(mocks);
        fflib_ISObjectUnitOfWork mockUow = mockUnitOfWork(mocks);

        Id accountId = fflib_IDGenerator.generate(Account.SObjectType);
        Opportunity first = makeOpportunity(
            'Acme Expansion',
            accountId,
            fflib_IDGenerator.generate(User.SObjectType),
            'Closed Won',
            Date.newInstance(2024, 1, 31),
            1000
        );
        Opportunity second = makeOpportunity(
            'Globex Rollout',
            accountId,
            fflib_IDGenerator.generate(User.SObjectType),
            'Closed Won',
            Date.newInstance(2023, 12, 31),
            null
        );
        List<Opportunity> selected = new List<Opportunity>{ first, second };
        Set<Id> opportunityIds = new Set<Id>{ first.Id, second.Id };

        stubSelectById(mocks, mockSelector, opportunityIds, selected);

        Test.startTest();
        RenewalService.createRenewals(opportunityIds);
        Test.stopTest();

        // The selector was queried once with exactly the requested ids.
        ((IOpportunitiesSelector) mocks.verify(mockSelector, mocks.times(1))).selectById(opportunityIds);

        Opportunity expectedFirstRenewal = expectedRenewalFor(first);
        Opportunity expectedSecondRenewal = expectedRenewalFor(second);

        // Each renewal is registered via the single-record registerNew(SObject) overload exactly
        // once, with the contracted field values (uplifted Amount rounded to 2 decimals, one year
        // out CloseDate, 'Prospecting' stage, original AccountId, suffixed Name).
        ((fflib_ISObjectUnitOfWork) mocks.verify(mockUow, mocks.times(1))).registerNew(expectedFirstRenewal);
        ((fflib_ISObjectUnitOfWork) mocks.verify(mockUow, mocks.times(1))).registerNew(expectedSecondRenewal);

        // Each reminder Task is registered via registerNew(task, Task.WhatId, renewal) exactly once,
        // related to the NEW renewal (id-less, 'Prospecting') and never to the original opportunity,
        // with the contracted Subject, OwnerId (the original opportunity's owner) and ActivityDate
        // (the renewal's CloseDate minus 60 days).
        ((fflib_ISObjectUnitOfWork) mocks.verify(mockUow, mocks.times(1)))
            .registerNew(expectedReminderFor(first, expectedFirstRenewal), Task.WhatId, expectedFirstRenewal);
        ((fflib_ISObjectUnitOfWork) mocks.verify(mockUow, mocks.times(1)))
            .registerNew(expectedReminderFor(second, expectedSecondRenewal), Task.WhatId, expectedSecondRenewal);

        // The original opportunities must never be registered as the task's related record.
        ((fflib_ISObjectUnitOfWork) mocks.verify(mockUow, mocks.times(0)))
            .registerNew(expectedReminderFor(first, expectedFirstRenewal), Task.WhatId, first);
        ((fflib_ISObjectUnitOfWork) mocks.verify(mockUow, mocks.times(0)))
            .registerNew(expectedReminderFor(second, expectedSecondRenewal), Task.WhatId, second);

        // commitWork is called exactly once when something was registered.
        ((fflib_ISObjectUnitOfWork) mocks.verify(mockUow, mocks.times(1))).commitWork();
    }

