@isTest
private class OpportunitiesServiceTest {

    // A valid, mid-range discount used on the happy paths. The service must pass the
    // percentage through unchanged, so we verify the domain is called with this exact value.
    private static final Decimal VALID_DISCOUNT = 25;

    private static fflib_ApexMocks mocks;
    private static IOpportunitiesSelector mockSelector;
    private static IOpportunities mockDomain;
    private static fflib_ISObjectUnitOfWork mockUow;

    // Creates fresh mocks for every test and injects them into the Application factories,
    // so no SOQL and no DML can ever happen: the selector, the domain and the unit of
    // work are all mocked.
    //
    // Important: the fflib Application factories register the injected mocks by their
    // SObjectType, which they obtain by calling getSObjectType() on the mock itself.
    // An unstubbed ApexMocks method returns null, so getSObjectType() must be stubbed
    // BEFORE injecting, otherwise the mock is registered under a null key and the
    // factory silently falls back to the real implementation.
    private static void injectMocks() {
        mocks = new fflib_ApexMocks();
        mockSelector = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        mockDomain = (IOpportunities) mocks.mock(IOpportunities.class);
        mockUow = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);

        mocks.startStubbing();
        mocks.when(mockSelector.getSObjectType()).thenReturn(Opportunity.SObjectType);
        mocks.when(mockDomain.getSObjectType()).thenReturn(Opportunity.SObjectType);
        mocks.stopStubbing();

        Application.Selector.setMock(mockSelector);
        Application.Domain.setMock((fflib_ISObjectDomain) mockDomain);
        Application.UnitOfWork.setMock(mockUow);
    }

    private static Set<Id> generateIds(Integer count) {
        Set<Id> ids = new Set<Id>();
        for (Integer i = 0; i < count; i++) {
            ids.add(fflib_IDGenerator.generate(Opportunity.SObjectType));
        }
        return ids;
    }

    private static List<Opportunity> recordsFor(Set<Id> oppIds) {
        List<Opportunity> records = new List<Opportunity>();
        for (Id oppId : oppIds) {
            records.add(new Opportunity(
                Id = oppId,
                Name = 'Test Opportunity',
                Amount = 100.00
            ));
        }
        return records;
    }

    // Stubs the selector so that selectById(ids) returns opportunities built from fake ids.
    private static void stubSelector(Set<Id> oppIds) {
        mocks.startStubbing();
        mocks.when(mockSelector.selectById(oppIds)).thenReturn(recordsFor(oppIds));
        mocks.stopStubbing();
    }

    // Happy-path verification: the selector is queried exactly once with the given ids,
    // the domain receives applyDiscount exactly once with the percentage unchanged and the
    // unit of work injected via Application.UnitOfWork, and commitWork() runs exactly once.
    private static void verifyDiscountAppliedAndCommitted(Set<Id> oppIds, Decimal discountPercentage) {
        ((IOpportunitiesSelector) mocks.verify(mockSelector, mocks.times(1)))
            .selectById(oppIds);
        ((IOpportunities) mocks.verify(mockDomain, mocks.times(1)))
            .applyDiscount(discountPercentage, mockUow);
        ((fflib_ISObjectUnitOfWork) mocks.verify(mockUow, mocks.times(1)))
            .commitWork();
    }

    // Verification for the "nothing happens" rules: the selector is never queried with
    // these ids, applyDiscount is never called on the domain and commitWork is never
    // called, i.e. nothing is selected, applied or committed.
    private static void verifyNothingHappened(Set<Id> oppIds, Decimal discountPercentage) {
        if (oppIds != null) {
            ((IOpportunitiesSelector) mocks.verify(mockSelector, mocks.never()))
                .selectById(oppIds);
        } else {
            ((IOpportunitiesSelector) mocks.verify(mockSelector, mocks.never()))
                .selectById(null);
        }
        ((IOpportunities) mocks.verify(mockDomain, mocks.never()))
            .applyDiscount(discountPercentage, mockUow);
        ((fflib_ISObjectUnitOfWork) mocks.verify(mockUow, mocks.never()))
            .commitWork();
    }

    // Shared assertion for the invalid-percentage rule: the service must throw
    // OpportunitiesServiceException and neither the selector, the domain nor the
    // unit of work may be touched at all (no query, no apply, no commit).
    private static void assertInvalidPercentageRejected(Decimal discountPercentage) {
        Set<Id> oppIds = generateIds(2);
        try {
            OpportunitiesService.applyDiscounts(oppIds, discountPercentage);
            System.assert(
                false,
                'Expected OpportunitiesServiceException for discount percentage: ' + discountPercentage
            );
        } catch (OpportunitiesService.OpportunitiesServiceException e) {
            // Expected: the discount percentage is outside the allowed range.
        }
        verifyNothingHappened(oppIds, discountPercentage);
    }

