/**
 * Opportunity domain class (Apex Enterprise Patterns / fflib).
 *
 * Validation rules implemented in the domain's validation hook (onValidate):
 *
 *   1. On insert and on update, Amount must not be negative.
 *      Error message: "Amount cannot be negative."
 *
 *   2. On update, an opportunity whose stage was already 'Closed Won' before
 *      the update cannot have its Amount changed. Closing an opportunity as
 *      won and changing its amount in the same update is allowed, because the
 *      pre-update stage is not yet 'Closed Won' in that case.
 *      Error message: "Amount cannot change on a won opportunity."
 *
 * Errors are raised through the domain's error(message, record, field) helper
 * so they are attached to the Amount field of the offending record only
 * (records in the same DML that pass validation still save) and are recorded
 * in fflib_SObjectDomain.Errors for unit test assertions.
 *
 * The rules are bulk-safe (single pass over the in-scope records) and need
 * no SOQL: pre-update values are taken from the trigger's old context.
 */
public inherited sharing class Opportunities extends fflib_SObjectDomain
{
    private static final String STAGE_CLOSED_WON = 'Closed Won';

    public Opportunities(List<Opportunity> records)
    {
        super(records);
    }

    /**
     * Standard fflib constructable inner class, used by
     * fflib_SObjectDomain.triggerHandler to route trigger events here.
     */
    public class Constructor implements fflib_SObjectDomain.IConstructable
    {
        public fflib_SObjectDomain construct(List<SObject> sObjectList)
        {
            return new Opportunities(sObjectList);
        }
    }

    /**
     * Validation hook invoked by the base class on insert and update.
     */
    public override void onValidate()
    {
        // Pre-update records are only available in an update trigger context.
        // Referencing the trigger context directly keeps this SOQL-free and
        // bulk-safe; outside trigger context it is simply null, which makes
        // rule 2 a no-op (rule 1 still applies).
        Map<Id, SObject> recordsBeforeUpdate = Trigger.isUpdate ? Trigger.oldMap : null;

        for (Opportunity record : (List<Opportunity>) records)
        {
            // Rule 1: on insert and on update, Amount must not be negative.
            // A null Amount is permitted (not a required field).
            if (record.Amount != null && record.Amount < 0)
            {
                error('Amount cannot be negative.', record, Opportunity.Amount);
            }

            // Rule 2: on update only - once an opportunity is already
            // 'Closed Won', its Amount can no longer change.
            if (recordsBeforeUpdate != null)
            {
                Opportunity beforeUpdate = (Opportunity) recordsBeforeUpdate.get(record.Id);

                // Same-update close-as-won plus amount change is allowed:
                // the pre-update stage is then not 'Closed Won'.
                if (beforeUpdate.StageName == STAGE_CLOSED_WON
                    && record.Amount != beforeUpdate.Amount)
                {
                    error('Amount cannot change on a won opportunity.', record, Opportunity.Amount);
                }
            }
        }
    }
}
