            Opportunity.Id,
            Opportunity.Name,
            Opportunity.AccountId,
            Opportunity.StageName,
            Opportunity.Amount,
            Opportunity.CloseDate
        };
    }

    public List<Opportunity> selectById(Set<Id> opportunityIds) {
        return (List<Opportunity>) selectSObjectsById(opportunityIds);
    }

    /**
     * Returns the open opportunities (IsClosed = false) of the given accounts,
     * highest Amount first; opportunities without an Amount come after all
     * others (Amount DESC NULLS LAST); equal amounts are ordered by CloseDate
     * ascending (earliest first), with opportunity Name as a final
     * deterministic tiebreaker.
     *
     * The query is built from the selector's query factory (newQueryFactory()),
     * so the selector's standard field list and its security configuration keep
     * applying. The account Ids are passed as a SOQL bind variable, so the
     * condition is bulk-safe and injection-safe. Executes as a single query,
     * returning at most maxRecords rows.
     *
     * @param accountIds  parent account Ids; must be non-empty
     * @param maxRecords  maximum number of rows to return; null means no limit
     * @return matching opportunities, each including the parent account's Name
     *         (accessible via Opportunity.Account.Name)
     */
    public List<Opportunity> selectTopOpenByAccountIds(Set<Id> accountIds, Integer maxRecords) {
        // Guard: nothing to query
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Opportunity>();
        }

        // Factory pre-populated with the selector's standard field list and its
        // security configuration (newQueryFactory() applies enforceSecurity()).
        fflib_QueryFactory queryFactory = newQueryFactory();

        // Open opportunities of the given accounts; bind variable keeps the
        // condition bulk-safe and injection-safe.
        queryFactory.setCondition('AccountId IN :accountIds AND IsClosed = false');

        String soql = queryFactory.toSoql();

        // Add the parent account's Name to the selector's standard field list,
        // returned through the relationship as Opportunity.Account.Name. The
        // generated SOQL always starts with "SELECT <fields> FROM <object>",
        // so the extra field is spliced in just before the FROM clause.
        Integer fromIndex = soql.indexOf(' FROM ');
        if (fromIndex < 0) {
            throw new IllegalStateException('Unexpected SOQL generated by fflib_QueryFactory: ' + soql);
        }
        soql = soql.substring(0, fromIndex) + ', Account.Name' + soql.substring(fromIndex);

        // Highest Amount first, NULLS LAST so rows without an Amount sort after
        // all others; then earliest CloseDate; then Name as a stable tiebreaker.
        soql += ' ORDER BY Amount DESC NULLS LAST, CloseDate ASC, Name ASC';

        // At most maxRecords rows, applied within the same single query.
        // (maxRecords is an Integer, so concatenation is injection-safe.)
        if (maxRecords != null) {
            if (maxRecords < 0) {
                throw new IllegalArgumentException('maxRecords must not be negative');
            }
            soql += ' LIMIT ' + maxRecords;
        }

        return (List<Opportunity>) Database.query(soql);
    }
}
