    /**
     * Base fields plus whatever fields the admins have placed on the
     * Credit_Review field set (currently AnnualRevenue and Rating). The
     * field set is read dynamically, so admins can add or remove fields
     * without any code change here.
     */
    public List<Schema.SObjectField> getSObjectFieldList() {
        List<Schema.SObjectField> fieldList = new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };

        Schema.FieldSet creditReviewFieldSet =
            Account.SObjectType.fieldSets.getMap().get(CREDIT_REVIEW_FIELD_SET);

        if (creditReviewFieldSet != null) {
            for (Schema.FieldSetMember member : creditReviewFieldSet.getFields()) {
                fieldList.add(member.getSObjectField());
            }
        }

        return fieldList;
    }

    /**
     * Returns the requested accounts, selected in user mode (the selector's
     * data access setting) with this selector's field list, which includes
     * the Credit_Review field set fields.
     */
    public List<Account> selectById(Set<Id> accountIds) {
        return queryAccounts('Id IN :accountIds', accountIds, null);
    }

    /**
     * Returns the requested accounts together with their Contacts child
     * records in a single query.
     *
     * The account fields come from this selector's field list (including the
     * Credit_Review field set fields); the contact fields of the child
     * subquery come from the existing ContactsSelector, so they always match
     * that selector's field list without duplication.
     *
     * The query runs in user mode (the selector's data access setting),
     * which enforces object CRUD, field FLS and sharing on the whole
     * statement, including the Contacts subquery. The FROM Contacts
     * relationship restricts the child rows to the accounts being queried,
     * so no additional condition is needed in the subquery.
     */
    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        List<String> contactFieldNames = new List<String>();
        for (Schema.SObjectField contactField : new ContactsSelector().getSObjectFieldList()) {
            contactFieldNames.add(contactField.getDescribe().getName());
        }

        String contactsSubQuery = '(SELECT '
            + String.join(contactFieldNames, ', ')
            + ' FROM Contacts)';

        return queryAccounts('Id IN :accountIds', accountIds, contactsSubQuery);
    }

    /**
     * Builds and runs the account query:
     *  - fields: this selector's field list (base fields + Credit_Review
     *    field set fields), de-duplicated;
     *  - optional child subquery (e.g. Contacts from ContactsSelector);
     *  - condition: Id IN :accountIds (bind variable, injection-safe);
     *  - executes with the selector's data access setting (user mode), so
     *    object, field and sharing security are enforced by the platform.
     */
    private List<Account> queryAccounts(String condition, Set<Id> accountIds, String subQuery) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }

        List<String> fieldNames = new List<String>();
        for (Schema.SObjectField field : getSObjectFieldList()) {
            String fieldName = field.getDescribe().getName();
            if (!fieldNames.contains(fieldName)) {
                fieldNames.add(fieldName);
            }
        }

        String soql = 'SELECT ' + String.join(fieldNames, ', ');
        if (subQuery != null) {
            soql += ', ' + subQuery;
        }
        soql += ' FROM Account WHERE ' + condition + ' ORDER BY Id';

        return (List<Account>) Database.query(soql, accessLevel);
    }
