            ));

            closedCount++;
        }

        // Events are registered to be published by the unit of work only after
        // the opportunity DML has succeeded. If the DML fails, commitWork throws
        // before any Deal_Won__e is published.
        unitOfWork.registerPublishAfterTransaction(eventsToPublish);

        // Single commit of updates and event publishing.
        unitOfWork.commitWork();

        return closedCount;
    }
