public inherited sharing class ErpCustomerSync implements Queueable, Database.AllowsCallouts {

    /**
     * Sends every newly created Account to the ERP as a customer, one HTTP
     * request per account, so the ERP team can trace each account on its own.
     *
     * The callout is made from a Queueable (implements Database.AllowsCallouts)
     * because the platform does not permit synchronous HTTP callouts directly
     * from a trigger context: the trigger runs before the DML transaction is
     * committed, and Apex raises an unrecoverable exception for callouts made
     * in that context.
     */

    @TestVisible
    private static final String ERP_ENDPOINT = 'callout:ERP/api/customers';

    /**
     * Salesforce allows at most 100 callouts in a single transaction, so each
     * queued job is responsible for at most this many accounts.
     */
    @TestVisible
    private static final Integer MAX_ACCOUNTS_PER_JOB = 100;

    /**
     * A single transaction may enqueue up to 50 Queueable jobs. Together with
     * MAX_ACCOUNTS_PER_JOB this covers batches of up to 5,000 accounts, well
     * beyond the 200-record marketplace batches in scope for this ticket.
     */
    @TestVisible
    private static final Integer MAX_JOBS_PER_TRANSACTION = 50;

    /** The chunk of accounts this job instance is responsible for. */
    private final List<Account> accounts;

    public ErpCustomerSync(List<Account> accounts) {
        this.accounts = accounts;
    }

    /**
     * Entry point called from the Account trigger. Accepts the full batch of
     * inserted accounts (1 for a single user insert, up to 200 from the
     * marketplace integration) and queues the callout work.
     *
     * The batch is split into chunks of MAX_ACCOUNTS_PER_JOB and one Queueable
     * is enqueued per chunk. Deliberately, no job chains another job
     * (enqueueJob from inside execute): chained jobs execute synchronously on
     * the same stack when Test.stopTest runs and can exceed the platform's
     * maximum stack depth, and chunking up front keeps every job well inside
     * the 100-callouts-per-transaction limit without any chaining.
     */
    public static void enqueueNewAccounts(List<Account> newAccounts) {
        if (newAccounts == null || newAccounts.isEmpty()) {
            return;
        }

        Integer jobCount = 0;
        List<Account> chunk = new List<Account>();

        for (Account account : newAccounts) {
            if (jobCount >= MAX_JOBS_PER_TRANSACTION) {
                // Batches beyond 5,000 accounts are out of scope for this
                // ticket (marketplace batches are at most 200).
                break;
            }

            chunk.add(account);

            if (chunk.size() == MAX_ACCOUNTS_PER_JOB) {
                System.enqueueJob(new ErpCustomerSync(chunk));
                jobCount++;
                chunk = new List<Account>();
            }
        }

        // Enqueue the final partial chunk, if any.
        if (!chunk.isEmpty() && jobCount < MAX_JOBS_PER_TRANSACTION) {
            System.enqueueJob(new ErpCustomerSync(chunk));
        }
    }

    /**
     * Performs one ERP callout per account in this job's chunk. Each request
     * carries a JSON array with exactly one customer element, per the ERP
     * contract, so the ERP team can trace every account on its own.
     * A 202 Accepted response is expected; error handling and retries are out
     * of scope for this ticket, so the response is not further inspected.
     */
    public void execute(QueueableContext context) {
        for (Account account : accounts) {
            sendSingleCustomer(account);
        }
    }

    /**
     * Performs one POST to the ERP for a single account. The body is a JSON
     * array with exactly one customer element, per the ERP contract:
     *   [{"salesforceId": "<18-char Id>", "name": "<Name>", "country": <BillingCountry or null>}]
     */
    @TestVisible
    private static void sendSingleCustomer(Account account) {
        ErpCustomer customer = new ErpCustomer(
            account.Id,
            account.Name,
            account.BillingCountry
        );

        HttpRequest request = new HttpRequest();
        request.setEndpoint(ERP_ENDPOINT);
        request.setMethod('POST');
        request.setHeader('Content-Type', 'application/json');
        // Serializing a single-element list produces the required JSON array
        // and correctly emits "country": null when BillingCountry is blank.
        request.setBody(JSON.serialize(new List<ErpCustomer>{ customer }));

        HttpResponse response = new Http().send(request);
        // Expected: 202 Accepted. Error handling/retries out of scope.
    }

    /**
     * JSON payload structure expected by the ERP. Public fields serialize
     * directly; JSON.serialize handles escaping of special characters.
     */
    @TestVisible
    private class ErpCustomer {
        public String salesforceId;
        public String name;
        public String country;

        public ErpCustomer(String salesforceId, String name, String country) {
            this.salesforceId = salesforceId;
            this.name = name;
            this.country = country;
        }
    }
}
