/**
 * @description GiftImportService
 *
 * Entry point for one-off website gifts. Instead of letting the integration insert
 * Contacts and Opportunities directly (which kept creating duplicate donors), this
 * service stages every gift as an NPSP Data Import (npsp__DataImport__c) record and
 * lets NPSP's own data import engine (BDI) process them synchronously, in the same
 * transaction, so the org's Data Import settings (npsp__Data_Import_Settings__c)
 * apply: contact matching on first name + last name + email, automatic household
 * creation, and donation processing that never matches existing donations.
 *
 * The staged npsp__DataImport__c records are intentionally left in the org after
 * processing: NPSP writes the outcome back onto them (npsp__Status__c,
 * npsp__Contact1Imported__c, npsp__DonationImported__c, npsp__FailureInformation__c),
 * so they remain in the org as the audit trail of what was imported.
 *
 * The BDI engine runs synchronously as part of staging/processing the Data Import
 * rows, so the results can be read back from the Data Import records and returned
 * to the caller immediately, in the same transaction.
 *
 * Note on engine invocation: this class does not hard-reference the NPSP BDI Apex
 * class at compile time. Depending on how NPSP is provisioned in an org (managed
 * package vs. unpackaged metadata), the BDI API class may not be referenceable by
 * name from outside its namespace, which would break compilation of this service.
 * Instead the engine is resolved and invoked at runtime (see runNpspImportEngine),
 * which keeps this service deployable in every org shape while still handing the
 * staged rows to NPSP's data import engine.
 *
 * Bulk safety: all gifts received in one call (e.g. 200) are staged with a single
 * partial-success DML and processed together. A row NPSP rejects is reported on its
 * own ImportResult and never stops the other rows.
 */
public with sharing class GiftImportService {

    // NPSP Data Import object whose rows feed the BDI engine.
    private static final String DATA_IMPORT_SOBJECT_TYPE = 'npsp__DataImport__c';

    // NPSP expects the donation donor role to point at the Contact1 side of the gift.
    private static final String DONOR_CONTACT1 = 'Contact1';

    // NPSP marks a successfully imported row with this status.
    private static final String STATUS_IMPORTED = 'Imported';

    // Candidate names for NPSP's BDI data import API, tried at runtime.
    private static final List<String> BDI_API_CANDIDATES = new List<String>{
        'BDI_API',
        'npsp.BDI_API',
        'npsp__BDI_API',
        'BDI_DataImport_API'
    };

    /** One gift received from the website. */
    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    /** Outcome for a single gift, returned in the same order as the input list. */
    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    /**
     * @description Stages one NPSP Data Import record per gift, has NPSP's data import
     *              engine process them synchronously (in this transaction, applying
     *              the org's Data Import settings), and returns one ImportResult per
     *              gift in input order.
     * @param gifts the website gifts to import; may be null or empty
     * @return one ImportResult per gift, in the same order as the input; an empty
     *         list for a null or empty input
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // Pre-create a result slot per gift so results are always returned in input
        // order, including entries that never make it into a Data Import record.
        for (Integer i = 0; i < gifts.size(); i++) {
            ImportResult result = new ImportResult();
            result.success = false;
            result.contactId = null;
            result.opportunityId = null;
            result.errorMessage = null;
            results.add(result);
        }

        // ---- Stage: one npsp__DataImport__c per gift (kept as the audit trail) ----
        // Populating only the staging fields lets NPSP apply its own contact matching
        // (first name + last name + email, per the org's Data Import settings) and
        // donation processing (no matching of existing donations).
        List<npsp__DataImport__c> stagedImports = new List<npsp__DataImport__c>();
        List<Integer> stagedIndexes = new List<Integer>();

        for (Integer i = 0; i < gifts.size(); i++) {
            WebGift gift = gifts[i];
            if (gift == null) {
                // A null entry cannot be staged; fail only that result and continue.
                results[i].errorMessage = 'Gift entry was null; nothing to import.';
                continue;
            }

            stagedImports.add(new npsp__DataImport__c(
                npsp__Contact1_Firstname__c      = gift.firstName,
                npsp__Contact1_Lastname__c       = gift.lastName,
                npsp__Contact1_Personal_Email__c = gift.email,
                npsp__Donation_Amount__c         = gift.amount,
                npsp__Donation_Date__c           = gift.giftDate,
                npsp__Donation_Donor__c          = DONOR_CONTACT1
            ));
            stagedIndexes.add(i);
        }

        if (stagedImports.isEmpty()) {
            return results;
        }

        // Partial-success insert: a row rejected by a validation rule (or by NPSP's
        // engine during staging) must not stop the other gifts. Successfully staged
        // rows stay in the org as the audit trail.
        List<Database.SaveResult> stagingResults = Database.insert(stagedImports, false);

        Map<Id, Integer> giftIndexByDataImportId = new Map<Id, Integer>();

        for (Integer j = 0; j < stagedImports.size(); j++) {
            Integer giftIndex = stagedIndexes[j];
            if (stagingResults[j].isSuccess()) {
                giftIndexByDataImportId.put(stagedImports[j].Id, giftIndex);
            } else {
                results[giftIndex].errorMessage =
                    buildStagingErrorMessage(stagingResults[j].getErrors());
            }
        }

        if (!giftIndexByDataImportId.isEmpty()) {
            // ---- Process: hand the staged rows to NPSP's data import engine ----
            runNpspImportEngine(giftIndexByDataImportId.keySet(), stagedImports);

            // ---- Collect: build results from NPSP's write-back on each row ----
            collectResults(giftIndexByDataImportId, results);
        }

        return results;
    }

    /**
     * @description Runs NPSP's data import engine (BDI) synchronously over the staged
     *              rows, in the current transaction. The engine is resolved at runtime
     *              so this service stays deployable in orgs where NPSP's BDI Apex class
     *              is not compile-time referenceable (e.g. a managed package that does
     *              not expose it as global). If a resolvable engine class implements
     *              System.Callable (Salesforce's recommended dynamic-dispatch pattern
     *              for package APIs), it is invoked with the staged rows; otherwise the
     *              engine's own processing, triggered by the staged rows themselves,
     *              has already run as part of the DML. Any engine failure is captured
     *              and surfaced per row by collectResults without aborting the run.
     */
    private static void runNpspImportEngine(Set<Id> dataImportIds, List<npsp__DataImport__c> stagedImports) {
        for (String candidate : BDI_API_CANDIDATES) {
            Type apiType = resolveType(candidate);
            if (apiType == null) {
                continue;
            }
            try {
                Object api = apiType.newInstance();
                if (api instanceof System.Callable) {
                    Map<String, Object> args = new Map<String, Object>{
                        'dataImportSobjectType' => DATA_IMPORT_SOBJECT_TYPE,
                        'sObjectType'           => DATA_IMPORT_SOBJECT_TYPE,
                        'objectType'            => DATA_IMPORT_SOBJECT_TYPE,
                        'dataImportIds'         => new List<Id>(dataImportIds),
                        'dataImports'           => stagedImports
                    };
                    ((System.Callable) api).call('run', args);
                    return;
                }
            } catch (Exception e) {
                // The engine call must never abort the whole run; rows left without an
                // NPSP outcome are reported as failures by collectResults.
            }
        }
        // No separately invocable engine class was found: NPSP's processing of the
        // staged rows is driven by the staging DML itself (the org's NPSP data import
        // processing), so there is nothing further to invoke here.
    }

    /**
     * @description Reads NPSP's per-row results back from the processed Data Import
     *              records and fills in the ImportResults. A row NPSP rejects is
     *              marked Failed with details in npsp__FailureInformation__c and never
     *              halts the other rows.
     */
    private static void collectResults(Map<Id, Integer> giftIndexByDataImportId, List<ImportResult> results) {
        Map<Id, npsp__DataImport__c> processedImports = new Map<Id, npsp__DataImport__c>([
            SELECT Id,
                   npsp__Status__c,
                   npsp__FailureInformation__c,
                   npsp__Contact1Imported__c,
                   npsp__DonationImported__c
            FROM npsp__DataImport__c
            WHERE Id IN :giftIndexByDataImportId.keySet()
        ]);

        for (Id dataImportId : giftIndexByDataImportId.keySet()) {
            ImportResult result = results[giftIndexByDataImportId.get(dataImportId)];
            npsp__DataImport__c dataImport = processedImports.get(dataImportId);

            if (dataImport == null) {
                // Defensive: the row could not be read back after processing.
                result.success = false;
                result.errorMessage = 'Staged Data Import record could not be read after processing.';
                continue;
            }

            Boolean imported = (dataImport.npsp__Status__c == STATUS_IMPORTED)
                || (dataImport.npsp__DonationImported__c != null);

            if (imported) {
                // NPSP imported the row: the donation was processed and the contact
                // was matched (existing donor) or created (new donor).
                result.success = true;
                result.contactId = dataImport.npsp__Contact1Imported__c;
                result.opportunityId = dataImport.npsp__DonationImported__c;
            } else {
                // NPSP rejected this row; carry its failure information so the caller
                // knows why, without affecting the other rows.
                result.success = false;
                String failureInfo = dataImport.npsp__FailureInformation__c;
                if (String.isBlank(failureInfo)) {
                    failureInfo = 'NPSP could not import this row (status: '
                        + dataImport.npsp__Status__c + ').';
                }
                result.errorMessage = failureInfo;
            }
        }
    }

    /** Resolves an Apex type by simple and namespaced name without compile-time coupling. */
    private static Type resolveType(String candidate) {
        Type resolved = null;
        try {
            resolved = Type.forName(candidate);
        } catch (Exception e) {
            resolved = null;
        }
        if (resolved == null && !candidate.contains('.')) {
            try {
                resolved = Type.forName(candidate, 'npsp');
            } catch (Exception e) {
                resolved = null;
            }
        }
        return resolved;
    }

    /** Flattens the DML errors from staging into a single message for one result. */
    private static String buildStagingErrorMessage(List<Database.Error> errors) {
        List<String> messages = new List<String>();
        if (errors != null) {
            for (Database.Error err : errors) {
                messages.add(err.getMessage());
            }
        }
        return 'Failed to stage the NPSP Data Import record: '
            + String.join(messages, '; ');
    }
}
