/**
 * @description Creates a single new NPSP Household Account with all of the supplied
 *              contacts as its members and returns the household Account Id.
 *
 *              Design notes:
 *              - The Account is created with the Household Account record type
 *                (looked up by DeveloperName, never hard-coded), so NPSP treats it
 *                as a real household: NPSP's triggers compute the household Name
 *                and the members' greeting fields.
 *              - Account.Name is a platform-required field, so a temporary
 *                placeholder is supplied at insert time; NPSP's household naming
 *                runs when the members are inserted (contacts added to a household
 *                trigger a household rename) and replaces it. We never set the
 *                final household name ourselves.
 *              - Exactly one Account is created per call; the contacts are inserted
 *                with AccountId pointing at that household, so NPSP does not
 *                auto-create any additional (individual/empty) accounts.
 *              - The first contact in the list is stored as the household's
 *                primary contact via Account.npe01__One2OneContact__c.
 *              - The whole operation is a single transaction: if anything fails,
 *                the household Account and any contacts are rolled back, so no
 *                stray/empty household can be left behind.
 *              - The member list is built by simple `add()` calls (never with a
 *                sized List constructor, which pre-fills the list with null
 *                elements and would break the DML).
 */
public with sharing class HouseholdService {

    /** DeveloperName of the Household Account record type in this org. */
    private static final String HOUSEHOLD_RT_DEV_NAME = 'HH_Account';

    /**
     * Temporary value for the platform-required Account.Name field.
     * NPSP's household naming overwrites it once members are attached;
     * this value is never treated as the household's real name.
     */
    private static final String PENDING_NAME_PLACEHOLDER = 'New Household';

    /**
     * @description  Creates one NPSP Household Account containing every supplied
     *               contact, with members[0] as the household's primary contact.
     * @param        members  New Contacts (no Id, no AccountId required); must
     *               contain at least one valid Contact with the fields NPSP
     *               requires (e.g. LastName).
     * @return       The Id of the new household Account.
     * @throws       IllegalArgumentException if members is null, empty, or
     *               contains a null element; if the household record type cannot
     *               be resolved; or if DML fails (error surfaces unchanged).
     */
    public static Id createHousehold(List<Contact> members) {
        // ---- Input validation -------------------------------------------------
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException(
                'HouseholdService.createHousehold requires a non-empty list of contacts.'
            );
        }
        for (Contact member : members) {
            if (member == null) {
                throw new IllegalArgumentException(
                    'HouseholdService.createHousehold received a null contact in the members list.'
                );
            }
        }

        // ---- Resolve the Household record type (no hard-coded Ids) ------------
        Id householdRecordTypeId = getHouseholdRecordTypeId();

        // ---- Create the household Account -------------------------------------
        // RecordTypeId makes this a genuine NPSP household. Name is supplied only
        // to satisfy the platform-required field; NPSP renames the household when
        // the members below are inserted, and also generates the greetings.
        Account household = new Account(
            RecordTypeId = householdRecordTypeId,
            Name = PENDING_NAME_PLACEHOLDER
        );
        insert household;

        // ---- Insert all members into that household ----------------------------
        // Attach each caller-supplied Contact to the new household by setting
        // AccountId, then insert them in bulk. Assigning AccountId is what makes
        // NPSP treat each Contact as a household member (and prevents NPSP from
        // creating any other account for them). After the insert, the caller's
        // Contact instances carry their new record Ids.
        for (Contact member : members) {
            member.AccountId = household.Id;
        }
        insert members;

        // ---- Designate the primary contact --------------------------------------
        // NPSP stores the household's primary contact in npe01__One2OneContact__c.
        // The first member of the list becomes the primary contact; NPSP's Account
        // trigger validates the lookup and refreshes household naming/greetings
        // accordingly.
        update new Account(
            Id = household.Id,
            npe01__One2OneContact__c = members[0].Id
        );

        return household.Id;
    }

    /**
     * @description  Looks up the Household Account record type by DeveloperName so
     *               the code is record-type-Id agnostic and deployable across orgs.
     * @return       The Id of the HH_Account record type.
     * @throws       IllegalArgumentException if the record type is missing/misnamed,
     *               which would indicate an org configuration problem.
     */
    private static Id getHouseholdRecordTypeId() {
        List<RecordType> householdRecordTypes = [
            SELECT Id
            FROM RecordType
            WHERE SobjectType = 'Account'
              AND DeveloperName = :HOUSEHOLD_RT_DEV_NAME
              AND IsActive = true
            LIMIT 1
        ];
        if (householdRecordTypes.isEmpty()) {
            throw new IllegalArgumentException(
                'Household Account record type with DeveloperName "'
                    + HOUSEHOLD_RT_DEV_NAME
                    + '" was not found on Account in this org.'
            );
        }
        return householdRecordTypes[0].Id;
    }
}
