```apex
/**
 * @description Service for crediting peer-to-peer fundraisers with NPSP partial
 * soft credits (npsp__Partial_Soft_Credit__c) on opportunities.
 *
 * Design notes (limits budget for a 200-request call):
 *   - SOQL: 3 queries total (opportunities, opportunity contact roles, existing
 *     partial soft credits) - all bulkified, none in loops.
 *   - DML: at most 4 statements (OCR updates, OCR inserts, soft credit updates,
 *     soft credit inserts), each guarded so it only runs when there is work.
 *   - All validation happens up front, before any DML, so a single invalid
 *     request leaves the database untouched.
 */
public with sharing class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        // Null or empty input does nothing.
        if (requests == null || requests.isEmpty()) {
            return;
        }

        // ------------------------------------------------------------------
        // Phase 0: basic request hygiene and id collection (no DML yet).
        // ------------------------------------------------------------------
        Set<Id> opportunityIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            if (req.opportunityId == null) {
                throw new SoftCreditException('opportunityId is required for every soft credit request.');
            }
            if (req.contactId == null) {
                throw new SoftCreditException('contactId is required for every soft credit request.');
            }
            opportunityIds.add(req.opportunityId);
        }

        // ------------------------------------------------------------------
        // SOQL #1: opportunities being credited.
        // ------------------------------------------------------------------
        Map<Id, Opportunity> opportunities = new Map<Id, Opportunity>([
                SELECT Id, Amount, npsp__Primary_Contact__c
                FROM Opportunity
                WHERE Id IN :opportunityIds
        ]);

        // ------------------------------------------------------------------
        // SOQL #2: existing contact roles, indexed by (OpportunityId, ContactId).
        // Id map keys keep lookups case-insensitive.
        // ------------------------------------------------------------------
        Map<Id, Map<Id, OpportunityContactRole>> contactRolesByOpp =
                new Map<Id, Map<Id, OpportunityContactRole>>();
        for (OpportunityContactRole ocr : [
                SELECT Id, OpportunityId, ContactId, Role, IsPrimary
                FROM OpportunityContactRole
                WHERE OpportunityId IN :opportunityIds
        ]) {
            Map<Id, OpportunityContactRole> byContact = contactRolesByOpp.get(ocr.OpportunityId);
            if (byContact == null) {
                byContact = new Map<Id, OpportunityContactRole>();
                contactRolesByOpp.put(ocr.OpportunityId, byContact);
            }
            byContact.put(ocr.ContactId, ocr);
        }

        // ------------------------------------------------------------------
        // SOQL #3: existing partial soft credits, keyed by (Opportunity, Contact)
        // so we update instead of creating a duplicate.
        // ------------------------------------------------------------------
        Map<Id, Map<Id, npsp__Partial_Soft_Credit__c>> softCreditsByOpp =
                new Map<Id, Map<Id, npsp__Partial_Soft_Credit__c>>();
        for (npsp__Partial_Soft_Credit__c psc : [
                SELECT Id, npsp__Opportunity__c, npsp__Contact__c, npsp__Amount__c,
                       npsp__Role_Name__c, npsp__Contact_Role_ID__c
                FROM npsp__Partial_Soft_Credit__c
                WHERE npsp__Opportunity__c IN :opportunityIds
        ]) {
            Map<Id, npsp__Partial_Soft_Credit__c> byContact = softCreditsByOpp.get(psc.npsp__Opportunity__c);
            if (byContact == null) {
                byContact = new Map<Id, npsp__Partial_Soft_Credit__c>();
                softCreditsByOpp.put(psc.npsp__Opportunity__c, byContact);
            }
            byContact.put((Id) psc.npsp__Contact__c, psc);
        }

        // ------------------------------------------------------------------
        // Phase 1: validate the whole call before any DML.
        // ------------------------------------------------------------------
        for (SoftCreditRequest req : requests) {
            Opportunity opp = opportunities.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException(
                        'Opportunity ' + req.opportunityId + ' in a soft credit request was not found.');
            }

            // Never credit the opportunity's primary contact (that contact is
            // already credited by the opportunity itself).
            if (opp.npsp__Primary_Contact__c == req.contactId) {
                throw new SoftCreditException(
                        'Contact ' + req.contactId +
                        ' is the primary contact on opportunity ' + req.opportunityId +
                        ' and cannot receive a partial soft credit.');
            }

            if (req.amount == null) {
                throw new SoftCreditException(
                        'amount is required for the soft credit on opportunity ' +
                        req.opportunityId + ' for contact ' + req.contactId + '.');
            }
            if (req.amount <= 0) {
                throw new SoftCreditException(
                        'amount must be positive for the soft credit on opportunity ' +
                        req.opportunityId + ' for contact ' + req.contactId + '.');
            }
            if (opp.Amount != null && req.amount > opp.Amount) {
                throw new SoftCreditException(
                        'amount ' + req.amount +
                        ' exceeds the opportunity amount ' + opp.Amount +
                        ' on opportunity ' + req.opportunityId + '.');
            }
        }

        // ------------------------------------------------------------------
        // Phase 2: resolve contact roles.
        // The contact must end up with exactly one contact role on the
        // opportunity whose Role equals the requested role. Reuse (and re-role
        // if needed) an existing role, e.g. NPSP's 'Household Member', or
        // create a new non-primary role when none exists.
        //
        // For updates, build a fresh sObject carrying only the writable fields
        // (Id and Role). Reusing the queried record would attempt to write
        // fields that are not updateable on OpportunityContactRole (e.g.
        // IsPrimary), which raises a DML "fields being inaccessible" error.
        // ------------------------------------------------------------------
        List<OpportunityContactRole> rolesToUpdate = new List<OpportunityContactRole>();
        List<OpportunityContactRole> rolesToInsert = new List<OpportunityContactRole>();

        for (SoftCreditRequest req : requests) {
            Map<Id, OpportunityContactRole> byContact = contactRolesByOpp.get(req.opportunityId);
            OpportunityContactRole ocr = (byContact == null) ? null : byContact.get(req.contactId);

            if (ocr != null) {
                if (ocr.Role != req.role) {
                    rolesToUpdate.add(new OpportunityContactRole(
                            Id = ocr.Id,
                            Role = req.role
                    ));
                }
            } else {
                ocr = new OpportunityContactRole(
                        OpportunityId = req.opportunityId,
                        ContactId = req.contactId,
                        Role = req.role,
                        IsPrimary = false
                );
                rolesToInsert.add(ocr);
                // Register now; it will have an Id once inserted below.
                if (byContact == null) {
                    byContact = new Map<Id, OpportunityContactRole>();
                    contactRolesByOpp.put(req.opportunityId, byContact);
                }
                byContact.put(req.contactId, ocr);
            }
        }

        // DML #1 / #2 (conditional - empty lists consume no statements).
        if (!rolesToUpdate.isEmpty()) {
            update rolesToUpdate;
        }
        if (!rolesToInsert.isEmpty()) {
            insert rolesToInsert;
        }

        // ------------------------------------------------------------------
        // Phase 3: create or update the partial soft credits, linked to the
        // resolved contact role and carrying the same role name.
        // npsp__Contact_Name__c is not set here: it is populated by NPSP
        // (formula/automation from npsp__Contact__c) and is not writeable.
        // ------------------------------------------------------------------
        List<npsp__Partial_Soft_Credit__c> softCreditsToUpdate = new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> softCreditsToInsert = new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest req : requests) {
            OpportunityContactRole ocr = contactRolesByOpp.get(req.opportunityId).get(req.contactId);
            Map<Id, npsp__Partial_Soft_Credit__c> byContact = softCreditsByOpp.get(req.opportunityId);
            npsp__Partial_Soft_Credit__c psc = (byContact == null) ? null : byContact.get(req.contactId);

            if (psc != null) {
                // Existing partial soft credit for this contact on this
                // opportunity: update amount and role instead of duplicating.
                psc.npsp__Amount__c = req.amount;
                psc.npsp__Role_Name__c = req.role;
                psc.npsp__Contact_Role_ID__c = ocr.Id;
                softCreditsToUpdate.add(psc);
            } else {
                psc = new npsp__Partial_Soft_Credit__c(
                        npsp__Opportunity__c = req.opportunityId,
                        npsp__Contact__c = req.contactId,
                        npsp__Amount__c = req.amount,
                        npsp__Role_Name__c = req.role,
                        npsp__Contact_Role_ID__c = String.valueOf(ocr.Id)
                );
                softCreditsToInsert.add(psc);
            }
        }

        // DML #3 / #4 (conditional - empty lists consume no statements).
        if (!softCreditsToUpdate.isEmpty()) {
            update softCreditsToUpdate;
        }
        if (!softCreditsToInsert.isEmpty()) {
            insert softCreditsToInsert;
        }
    }
}
