/**
 * @description NPSP TDTM trigger handler for Opportunity.
 *
 * Creates a single follow-up Task ("Major gift thank-you call") when an
 * Opportunity is inserted as Closed Won with Amount >= 5000, or is updated so
 * that it becomes Closed Won with Amount >= 5000 when it was not already both
 * of those things. Editing an already-qualified gift creates no duplicate.
 *
 * IMPORTANT - visibility: NPSP runs as a managed package (namespace `npsp`).
 * Its TDTM dispatcher (TDTM_Trigger / TDTM_TriggerHandler) locates registered
 * handler classes by name at runtime via Type.forName(...) and instantiates
 * them from inside the npsp namespace. A class instantiated and virtually
 * dispatched from a managed package must be declared `global` (class and
 * overridden run method), exactly as documented in the NPSP customization
 * guide. A merely `public` class compiles fine but is not visible to the
 * package at runtime, so the dispatcher never runs it.
 *
 * Registration (done by the admin, no Apex trigger required):
 *   NPSP Settings > Trigger Configuration (npsp__Trigger_Handler__c):
 *     Class          = OPP_MajorGiftFollowUp_TDTM
 *     Object         = Opportunity
 *     Trigger Action = AfterInsert;AfterUpdate
 *     Load Order     = 5
 *     Asynchronous   = false
 *     Active         = true
 *
 * The dispatcher only invokes run() while that Trigger Handler record is
 * Active; deactivating the record stops the handler with no code change.
 *
 * Bulk safety: for 200 opportunities this handler executes 0 SOQL queries and
 * exactly 1 DML statement (a single bulk insert of the Tasks). Qualification
 * and the insert-vs-update transition check are derived purely from the
 * new/old record values passed in by the TDTM dispatcher, so no queries are
 * needed for idempotency.
 */
global with sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    private static final Decimal GIFT_THRESHOLD = 5000;
    private static final Integer FOLLOW_UP_DAYS_OFFSET = 3;
    private static final String WON_STAGE_NAME = 'Closed Won';
    private static final String TASK_SUBJECT = 'Major gift thank-you call';
    private static final String TASK_PRIORITY = 'High';
    private static final String TASK_STATUS = 'Not Started';

    /**
     * @description TDTM entry point called by the NPSP dispatcher.
     * @param newlist       The Opportunity records as they stand in this transaction.
     * @param oldlist       The pre-trigger Opportunity values (null/empty for AfterInsert).
     * @param triggerAction The trigger action being processed.
     * @param objResult     Describe result of the object being processed (Opportunity).
     * @return null; this handler performs its own single bulk DML statement.
     */
    global override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        List<Opportunity> newOpps = (List<Opportunity>) newlist;
        if (newOpps == null || newOpps.isEmpty()) {
            return null;
        }

        // Determine insert vs update from the presence of an old record image:
        // the dispatcher passes Trigger.old for updates and null/empty for
        // inserts. On update the old image is aligned with newlist by index.
        Boolean isUpdate = oldlist != null && !oldlist.isEmpty();
        List<Opportunity> oldOpps = isUpdate ? (List<Opportunity>) oldlist : null;

        List<Task> tasksToCreate = new List<Task>();

        Integer index = 0;
        for (Opportunity opp : newOpps) {
            if (qualifiesAsMajorGift(opp)) {
                // On update, skip opportunities that were already Closed Won
                // with Amount >= 5000 before this change (no duplicate tasks).
                Boolean alreadyQualified = false;
                if (isUpdate && oldOpps.size() > index) {
                    Opportunity oldOpp = oldOpps[index];
                    // Guard against the old and new images being the same
                    // object instance (only possible in direct invocations);
                    // in that case there is no meaningful prior state to
                    // compare, so treat it like an insert.
                    if (oldOpp != null && !(oldOpp === opp)) {
                        alreadyQualified = qualifiesAsMajorGift(oldOpp);
                    }
                }
                if (!alreadyQualified) {
                    tasksToCreate.add(buildFollowUpTask(opp));
                }
            }
            index++;
        }

        // Single bulk DML statement for the entire transaction.
        if (!tasksToCreate.isEmpty()) {
            insert tasksToCreate;
        }

        return null;
    }

    /**
     * @description True when the Opportunity is Closed Won with Amount >= 5000.
     *              IsWon is the authoritative flag on saved records; the
     *              StageName check makes the same determination for records
     *              evaluated before they are committed (e.g. in-memory records
     *              passed directly to run()), where the platform has not yet
     *              populated IsWon from the stage.
     * @param opp The Opportunity to evaluate (new or old image).
     * @return True if the Opportunity meets the major-gift criteria.
     */
    private Boolean qualifiesAsMajorGift(Opportunity opp) {
        if (opp == null) {
            return false;
        }
        Boolean isWon = opp.IsWon == true || opp.StageName == WON_STAGE_NAME;
        return isWon
            && opp.Amount != null
            && opp.Amount >= GIFT_THRESHOLD;
    }

    /**
     * @description Builds the follow-up Task for one qualified Opportunity.
     * @param opp The qualified Opportunity.
     * @return A Task ready for bulk insert.
     */
    private Task buildFollowUpTask(Opportunity opp) {
        Task followUp = new Task(
            Subject  = TASK_SUBJECT,
            Priority = TASK_PRIORITY,
            Status   = TASK_STATUS,
            WhatId   = opp.Id,
            OwnerId  = opp.OwnerId
        );

        // Primary contact may be null on the Opportunity.
        if (opp.npsp__Primary_Contact__c != null) {
            followUp.WhoId = opp.npsp__Primary_Contact__c;
        }

        // ActivityDate = CloseDate + 3 days; leave null if CloseDate is null.
        if (opp.CloseDate != null) {
            followUp.ActivityDate = opp.CloseDate + FOLLOW_UP_DAYS_OFFSET;
        }

        return followUp;
    }
}
