```apex
/**
 * @description Determines which records the running user is allowed to edit,
 * as reported by the UserRecordAccess object. UserRecordAccess is the only
 * mechanism that accounts for the full access calculation in one place:
 * object CRUD/FLS, record ownership, role hierarchy, sharing rules, manual
 * shares, Apex managed sharing, implicit parent access, and the
 * View All Data / Modify All Data / View All / Modify All permissions.
 *
 * A single SOQL query against UserRecordAccess can filter RecordId with an
 * IN list spanning multiple objects, so up to 2,000 IDs (the documented
 * per-call contract here) are resolved with exactly one query. To stay
 * bulk-safe if a caller ever exceeds the documented maximum, IDs are
 * processed in chunks of 2,000 per query, which keeps the 20-query budget
 * intact for the supported input size.
 *
 * Implementation note: the query is built with dynamic SOQL using the
 * record IDs as literal values. UserRecordAccess queries are subject to an
 * Apex compiler defect that rejects static SOQL containing bind variables
 * ("Variable does not exist: tmpVar1"), so the WHERE clause is constructed
 * as a string instead. Injection is not a concern: every value interpolated
 * into the query is a typed Id (validated by the platform when the Set<Id>
 * is built), so no arbitrary text can reach the query string.
 */
public with sharing class RecordAccessService {

    /**
     * @description Maximum number of record IDs evaluated per SOQL query.
     * Matches the documented per-call maximum so the normal case is one query.
     */
    private static final Integer CHUNK_SIZE = 2000;

    /**
     * @description Returns the subset of the given record IDs that the running
     * user can edit (UserRecordAccess.HasEditAccess = true).
     *
     * @param recordIds IDs possibly spanning multiple objects; may be null or empty.
     * @return The editable subset, deduplicated. Never null; an empty set when
     *         the input is null, empty, or contains no non-null IDs.
     */
    public static Set<Id> editableIds(Set<Id> recordIds) {
        // Contract: null or empty input yields an empty set, never null.
        if (recordIds == null || recordIds.isEmpty()) {
            return new Set<Id>();
        }

        // Normalize: drop nulls and duplicates so the query is not asked to
        // match a null RecordId and IDs are not evaluated twice.
        Set<Id> candidates = new Set<Id>();
        for (Id recordId : recordIds) {
            if (recordId != null) {
                candidates.add(recordId);
            }
        }
        if (candidates.isEmpty()) {
            return new Set<Id>();
        }

        Id userId = UserInfo.getUserId();
        Set<Id> editable = new Set<Id>();

        // Resolve access in chunks. One query covers the documented
        // 2,000-ID maximum; chunking merely protects callers that send more.
        for (List<Id> chunk : chunkIds(candidates)) {
            for (UserRecordAccess access : Database.query(buildSoql(userId, chunk))) {
                editable.add(access.RecordId);
            }
        }

        return editable;
    }

    /**
     * @description Builds the UserRecordAccess query for one chunk of record
     * IDs. Dynamic SOQL is used because the platform's Apex compiler rejects
     * bind variables in static SOQL against UserRecordAccess
     * ("Variable does not exist: tmpVar1").
     *
     * @param userId  The running user's Id.
     * @param recordIds The chunk of record Ids to evaluate.
     * @return A query string that returns the RecordId of every record in the
     *         chunk the user can edit.
     */
    private static String buildSoql(Id userId, List<Id> recordIds) {
        List<String> idLiterals = new List<String>();
        for (Id recordId : recordIds) {
            idLiterals.add('\'' + String.valueOf(recordId) + '\'');
        }

        return 'SELECT RecordId '
            + 'FROM UserRecordAccess '
            + 'WHERE UserId = \'' + String.valueOf(userId) + '\' '
            + 'AND HasEditAccess = true '
            + 'AND RecordId IN (' + String.join(idLiterals, ',') + ') '
            + 'LIMIT ' + CHUNK_SIZE;
    }

    /**
     * @description Splits the candidate IDs into chunks of at most CHUNK_SIZE
     * so each SOQL query stays within a predictable size.
     *
     * @param ids The deduplicated, non-null candidate IDs.
     * @return A list of ID chunks, each with at most CHUNK_SIZE elements.
     */
    private static List<List<Id>> chunkIds(Set<Id> ids) {
        List<List<Id>> chunks = new List<List<Id>>();
        List<Id> current = new List<Id>();
        for (Id id : ids) {
            current.add(id);
            if (current.size() == CHUNK_SIZE) {
                chunks.add(current);
                current = new List<Id>();
            }
        }
        if (!current.isEmpty()) {
            chunks.add(current);
        }
        return chunks;
    }
}
