```apex
/**
 * @description Reassigns ownership of Accounts and their child Contacts.
 *
 * Account trigger actions (territory recalculation) are intentionally skipped for
 * this ownership change by using the Trigger Actions Framework transaction-level
 * bypass for the whole Account sObject. Contact automation runs normally.
 *
 * The bypass is scoped strictly to this operation:
 *  - It is established only if Account is not already bypassed by the caller.
 *  - It is always cleared in a finally block, so Account automation behaves
 *    normally for the rest of the transaction whether reassign succeeds or not.
 *
 * DML is all-or-none (default `update` keyword) and exceptions propagate to the
 * caller unchanged.
 *
 * Limits: at most one SOQL query (Contacts) and two DML statements (Accounts,
 * Contacts), regardless of volume (callers pass up to 200 Accounts).
 *
 * @see Trigger Actions Framework 0.3.4 (unlocked, no namespace)
 */
public inherited sharing class AccountOwnershipService {

    /**
     * @description Sets OwnerId = newOwnerId on the given Accounts and on all
     *              Contacts of those Accounts.
     * @param accountIds Account Ids to reassign. Safe to call with an empty set.
     * @param newOwnerId User or Queue Id that will own the records.
     */
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        // Nothing to do: avoid spending DML/SOQL on an empty request.
        if (accountIds == null || accountIds.isEmpty() || newOwnerId == null) {
            return;
        }

        // Respect a pre-existing caller bypass: only clear what we set ourselves.
        // TAF's sObject-level bypass API lives on the TriggerBase class.
        Boolean accountWasAlreadyBypassed =
            TriggerBase.isBypassed(Schema.Account.SObjectType);
        if (!accountWasAlreadyBypassed) {
            TriggerBase.bypass(Schema.Account.SObjectType);
        }

        try {
            // DML statement 1 of 2: Accounts (all-or-none).
            // Contacts query (SOQL 1 of 1) is fetched before the Account update so
            // that both DML operations happen while the bypass is in effect.
            List<Contact> contactsToUpdate = getContactsForAccounts(accountIds);

            List<Account> accountsToUpdate = new List<Account>(accountIds.size());
            for (Id accountId : accountIds) {
                accountsToUpdate.add(new Account(Id = accountId, OwnerId = newOwnerId));
            }

            // All-or-none DML; throws DmlException on any failure, which we let
            // propagate to the caller unchanged.
            update accountsToUpdate;

            // DML statement 2 of 2: Contacts. Account bypass is still in effect
            // here, but the Contact trigger handler runs all actions normally.
            setContactOwners(contactsToUpdate, newOwnerId);
            update contactsToUpdate;
        } finally {
            // Restore Account automation for the remainder of the transaction,
            // whether the reassignment succeeded or failed.
            if (!accountWasAlreadyBypassed) {
                TriggerBase.clearBypass(Schema.Account.SObjectType);
            }
        }
    }

    /**
     * @description Single SOQL query fetching all Contacts of the given Accounts.
     * @param accountIds Parent Account Ids.
     * @return The child Contacts (possibly empty, never null).
     */
    private static List<Contact> getContactsForAccounts(Set<Id> accountIds) {
        return [
            SELECT Id
            FROM Contact
            WHERE AccountId IN :accountIds
        ];
    }

    /**
     * @description Applies the new owner to the given Contacts in memory.
     * @param contactsToUpdate Contacts to stamp (modified in place).
     * @param newOwnerId The new owner Id.
     */
    private static void setContactOwners(List<Contact> contactsToUpdate, Id newOwnerId) {
        for (Contact contact : contactsToUpdate) {
            contact.OwnerId = newOwnerId;
        }
    }
}
