/**
 * @description After update trigger action for Case: adds a private CaseComment
 *              when a case transitions to Closed. Bulk-safe: the comments for the
 *              entire batch are collected and inserted in a single DML statement,
 *              so closing 200 cases in one update works.
 *              Registered via Trigger_Action__mdt (After Update = Case, Order 10).
 */
public inherited sharing class TA_Case_AddClosureComment implements TriggerAction.AfterUpdate {

    private static final String CLOSED_STATUS = 'Closed';

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, SObject> oldMap = new Map<Id, SObject>(triggerOld);
        List<CaseComment> comments = new List<CaseComment>();
        for (SObject record : triggerNew) {
            Case c = (Case) record;
            Case old = (Case) oldMap.get(c.Id);
            if (c.Status == CLOSED_STATUS && old.Status != CLOSED_STATUS) {
                comments.add(new CaseComment(
                    ParentId = c.Id,
                    CommentBody = 'Case closed on ' + String.valueOf(Date.today()),
                    IsPublished = false
                ));
            }
        }
        if (!comments.isEmpty()) {
            insert comments;
        }
    }
}
