```apex
/**
 * Trigger Action for the Trigger Actions Framework (Case object).
 *
 * Keeps Account.FB_Open_Case_Count__c equal to the number of the account's Cases
 * with IsClosed = false. Cases without an Account are ignored. An account whose
 * last open case goes away is explicitly set to 0, never left blank.
 *
 * The count is always recomputed from a fresh aggregate query, so the action is
 * idempotent and self-correcting for every context it runs in: insert (open or
 * already closed), close, reopen, move to another account, delete and undelete.
 *
 * governor limits per trigger execution: at most two SOQL queries (one aggregate
 * on Case, one on Account) and at most one DML statement (update of only the
 * affected accounts whose stored value actually changes).
 */
public inherited sharing class TA_Case_RollupOpenCount
    implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate,
               TriggerAction.AfterDelete, TriggerAction.AfterUndelete {

    private static final String OPEN_COUNT_FIELD = 'FB_Open_Case_Count__c';

    // after insert: recalculate the accounts of the new cases. Cases created
    // already closed contribute nothing, but the parent account still gets its
    // correct value (0 instead of blank if it has no open cases).
    public void afterInsert(List<SObject> triggerNew) {
        recalculate(collectAccountIds(triggerNew));
    }

    // after update: recalculate only when IsClosed or AccountId changed
    // (close, reopen, move). When a case moves, both the old and the new
    // account are recalculated so neither is left stale.
    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Case> newCases = (List<Case>) triggerNew;
        List<Case> oldCases = (List<Case>) triggerOld;
        Set<Id> accountIds = new Set<Id>();
        for (Integer i = 0; i < newCases.size(); i++) {
            Case newCase = newCases[i];
            Case oldCase = oldCases[i];
            if (newCase.IsClosed != oldCase.IsClosed
                    || newCase.AccountId != oldCase.AccountId) {
                if (newCase.AccountId != null) {
                    accountIds.add(newCase.AccountId);
                }
                if (oldCase.AccountId != null) {
                    accountIds.add(oldCase.AccountId);
                }
            }
        }
        recalculate(accountIds);
    }

    // after delete: the deleted rows no longer appear in the aggregate query,
    // so the remaining counts, including 0, are written back.
    public void afterDelete(List<SObject> triggerOld) {
        recalculate(collectAccountIds(triggerOld));
    }

    // after undelete: the restored cases are visible to the aggregate query,
    // so the affected accounts get their counts back.
    public void afterUndelete(List<SObject> triggerNew) {
        recalculate(collectAccountIds(triggerNew));
    }

    // Collects the distinct, non-null AccountId values from the trigger records.
    // Cases without an account are ignored.
    private static Set<Id> collectAccountIds(List<SObject> records) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject record : records) {
            Id accountId = record.get('AccountId') == null ? null : (Id) record.get('AccountId');
            if (accountId != null) {
                accountIds.add(accountId);
            }
        }
        return accountIds;
    }

    // Recomputes the open case count for the given accounts and updates only
    // the accounts whose stored value differs (this also converts blank to 0).
    private static void recalculate(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            return;
        }

        // SOQL 1 of 2: current number of open cases per affected account.
        Map<Id, Integer> openCountByAccountId = new Map<Id, Integer>();
        for (AggregateResult row : [
            SELECT AccountId, COUNT(Id) openCases
            FROM Case
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) row.get('AccountId');
            Integer openCases = ((Decimal) row.get('openCases')).intValue();
            openCountByAccountId.put(accountId, openCases);
        }

        // SOQL 2 of 2: read the stored value so we only update accounts that
        // really change, and explicitly write 0 where no open cases remain.
        List<Account> accountsToUpdate = new List<Account>();
        for (Account account : [
            SELECT Id, FB_Open_Case_Count__c
            FROM Account
            WHERE Id IN :accountIds
        ]) {
            Integer targetCount = openCountByAccountId.containsKey(account.Id)
                ? openCountByAccountId.get(account.Id)
                : 0;
            Decimal storedCount = account.FB_Open_Case_Count__c;
            if (storedCount == null || storedCount.intValue() != targetCount) {
                Account changedAccount = new Account(Id = account.Id);
                changedAccount.FB_Open_Case_Count__c = targetCount;
                accountsToUpdate.add(changedAccount);
            }
        }

        // DML 1 of 1. Account has no trigger in this org, so updating Account
        // does not re-enter the Case trigger and no recursion guard is needed.
        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
```

